namespace SrpLab;
public sealed class LoanRiskScorer { public decimal Score(decimal amount,int credit,int employment,bool collateral) { decimal score=100m; score-=Math.Max(0,700-credit)*.15m; if(employment<6) score-=20m; if(amount>50000m&&!collateral) score-=25m; if(amount>150000m) score-=10m; return Math.Clamp(score,0m,100m); } }
public sealed class LoanEligibilityPolicy { public bool IsEligible(decimal risk,int credit) { return risk>=55m&&credit>=580; } }
public sealed class RequiredDocumentPolicy { public IReadOnlyList<string> Create(decimal amount,int employment,bool collateral,bool eligible) { var docs=new List<string>{"National ID","Proof of income (3 months)"}; if(amount>40000m) docs.Add("Bank statements (6 months)"); if(collateral) docs.Add("Collateral ownership deed"); if(employment<12) docs.Add("Employer letter"); if(!eligible) docs.Add("Manual underwriter referral form"); return docs; } }
public sealed class LoanDecisionLetterComposer { public string Compose(string name,decimal amount,decimal risk,bool eligible,IReadOnlyList<string> docs) { if(eligible) return $"Dear {name},\nYour request for {amount:C} is pre-approved (risk {risk:0}).\nPlease upload: {string.Join("; ",docs)}.\n"; return $"Dear {name},\nWe are unable to approve {amount:C} at this time.\nReference risk={risk:0}. You may reapply after improving documentation.\n"; } }
public sealed class UnderwriterCsvFormatter { public string Format(string id,int credit,int employment,bool collateral,decimal risk,bool eligible) { return $"{id},{credit},{employment},{(collateral?1:0)},{risk:0.00},{(eligible?"Y":"N")}"; } }
